UPDATE university_scholarships SET scholarship_name = 'Aalto University Excellence Scholarship', availability_status = 'available', funding_type = 'Full Tuition Waiver', max_scholarship = '100% tuition fee waiver for the normative degree duration (3 yrs bachelor''s, 2 yrs master''s); fees €12,000-15,000/yr (bachelor''s) and €15,000-20,000/yr (master''s) by field', covers_tuition = true, covers_living_expenses = false, valued_aspect = 'Top-ranked admission evaluation (very limited number)', eligibility_notes = 'For tuition-fee-liable (non-EU/EEA) applicants only; must tick the scholarship option on the admission application during the application period - no late scholarship applications. Granted competitively to highest-achieving applicants per programme (a programme may grant none); decision issued with the admission decision and cannot be appealed. Living costs (at least €800/month) are not covered. Bachelor''s Excellence holders graduating in target time with average >= 3.5 keep a 100% waiver into an Aalto master''s; new bachelor''s students instead get a 25% first-year reduction for accepting/paying within 21 days.', official_url = 'https://www.aalto.fi/en/admission-services/scholarships-and-tuition-fees', source_url = 'https://www.aalto.fi/en/admission-services/scholarships-and-tuition-fees', verification_status = 'verified', last_verified_at = now() WHERE id = 100;

UPDATE university_scholarships SET scholarship_name = 'University of Turku Merit Scholarship and Early Bird Discount', availability_status = 'available', funding_type = 'Tuition Waiver', max_scholarship = '50% tuition waiver from year 2 onward (fees mostly €10,000-12,000/yr); first year: €2,000 Early Bird discount for master''s students paying within 28 days - no first-year waiver', covers_tuition = true, covers_living_expenses = false, valued_aspect = 'Rule-based merit: 55 credits/year, average >= 3.0/5, 4 credits of Finnish', eligibility_notes = 'For fee-liable students who have paid their first year at Turku. Every student meeting the requirements gets the 50% waiver for the next year: 55 credits (bachelor''s: 110 across years 1-2 for a third-year waiver), grade average at least 3.0 on the 1-5 scale, and at least 4 credits of Finnish before the first application. Apply in the spring round (Admission Services invite eligible students). New master''s students: €2,000 Early Bird discount for accepting and paying within 28 days of the admission decisions (not for bachelor''s).', official_url = 'https://www.utu.fi/en/study-at-utu/scholarships-and-tuition-fees', source_url = 'https://www.utu.fi/en/study-at-utu/scholarships-and-tuition-fees', verification_status = 'verified', last_verified_at = now() WHERE id = 455;

UPDATE university_scholarships SET scholarship_name = 'University of Oulu Partial Tuition Fee Waiver Scholarships and Early Bird Discounts', availability_status = 'available', funding_type = 'Tuition Waiver', max_scholarship = 'Partial waiver of 10-40% by programme from year 2 onward (fees €8,500-14,000/yr master''s, €10,000 bachelor''s); first-year Early Bird discounts of 5-30% in selected programmes', covers_tuition = true, covers_living_expenses = false, valued_aspect = 'Study progress: at least 60 ECTS/year under the approved study plan (incl. Finnish studies)', eligibility_notes = 'Fee-liable bachelor''s and master''s students. Pay the first year (selected programmes: 5-30% Early Bird discount if paid within 3 weeks of the admission results; most programmes 30%). From year 2 the programme-specific waiver (10-40% master''s, 20-30% bachelor''s; one programme offers none) requires at least 60 ECTS completed in the preceding year per the approved study plan, including the Finnish language studies set for the programme. Page edition covers autumn 2026/spring 2027 admission rounds (2027-2028 start).', official_url = 'https://www.oulu.fi/en/apply/how-apply/university-oulu-tuition-fees-and-scholarships-for-international-applicants', source_url = 'https://www.oulu.fi/en/apply/how-apply/university-oulu-tuition-fees-and-scholarships-for-international-applicants', verification_status = 'verified', last_verified_at = now() WHERE id = 456;
